-- Datos sintéticos transaccionales: ROLLBACK siempre; sin cuentas persistentes.
begin;
select set_config('test.operador',gen_random_uuid()::text,true),set_config('test.otro',gen_random_uuid()::text,true),set_config('test.admin',gen_random_uuid()::text,true),set_config('test.token',gen_random_uuid()::text,true),set_config('test.solicitud',gen_random_uuid()::text,true);
insert into auth.users(id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) select current_setting('test.operador')::uuid,'authenticated','authenticated','op-test@example.invalid','{}','{"nombre":"Prueba transaccional"}',now(),now();
insert into auth.users(id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) select current_setting('test.otro')::uuid,'authenticated','authenticated','other-test@example.invalid','{}','{"nombre":"Prueba otro"}',now(),now();
insert into auth.users(id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) select current_setting('test.admin')::uuid,'authenticated','authenticated','admin-test@example.invalid','{}','{"nombre":"Prueba admin"}',now(),now();
update public.perfiles set activo=true,rol=case when user_id=current_setting('test.admin')::uuid then 'admin' else 'inspector' end where user_id in(current_setting('test.operador')::uuid,current_setting('test.otro')::uuid,current_setting('test.admin')::uuid);
select set_config('test.parq',(select id from public.parquimetros where activo order by id limit 1),true);
insert into public.tarifas(motivo,fundamento,monto,activa) values('SOLO PRUEBA','NO VIGENTE: prueba que se revierte',1,true) returning set_config('test.tarifa',id::text,true);
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',current_setting('test.operador'),'role','authenticated')::text,true);
do $$ declare t uuid; t2 uuid; r jsonb;r2 jsonb; m jsonb;m2 jsonb;blocked boolean:=false;begin
 t:=public.turno_operador('iniciar'); t2:=public.turno_operador('iniciar');if t is distinct from t2 then raise exception 'Turno no idempotente';end if;
 perform public.ubicacion_operador(28.1895,-105.4715,10);
 r:=public.reportar_falla_v2(current_setting('test.solicitud')::uuid,current_setting('test.token')::uuid,current_setting('test.parq'),'Prueba de falla','Solo prueba transaccional','','','TEST123',0);
 r2:=public.reportar_falla_v2(current_setting('test.solicitud')::uuid,current_setting('test.token')::uuid,current_setting('test.parq'),'Prueba de falla','Solo prueba transaccional','','','TEST123',0);
 if r->>'folio' is distinct from r2->>'folio' or r->>'gracia_hasta' is distinct from r2->>'gracia_hasta' then raise exception 'Reporte no idempotente';end if;
 if (r->>'gracia_hasta')::timestamptz-now()<>interval '15 minutes' then raise exception 'Gracia incorrecta';end if;
 perform set_config('test.folio',r->>'folio',true);
 begin perform public.reportar_falla_v2(gen_random_uuid(),gen_random_uuid(),current_setting('test.parq'),'Prueba falla','','','','TEST123',0);exception when others then blocked:=SQLERRM like '%gracia activa%';end;
 if not blocked then raise exception 'Duplicado no bloqueado';end if;blocked:=false;
 begin perform public.emitir_multa(gen_random_uuid(),current_setting('test.parq'),'TEST123',current_setting('test.tarifa')::uuid);exception when others then blocked:=SQLERRM like '%Gracia activa%';end;
 if not blocked then raise exception 'Multa durante gracia no bloqueada';end if;
 perform set_config('test.multa_solicitud',gen_random_uuid()::text,true);
 m:=public.emitir_multa(current_setting('test.multa_solicitud')::uuid,current_setting('test.parq'),'TEST999',current_setting('test.tarifa')::uuid);
 m2:=public.emitir_multa(current_setting('test.multa_solicitud')::uuid,current_setting('test.parq'),'TEST999',current_setting('test.tarifa')::uuid);
 if m->>'folio' is distinct from m2->>'folio' then raise exception 'Multa no idempotente';end if;
 if m->>'emisor_id' is distinct from current_setting('test.operador') then raise exception 'Autoría incorrecta';end if;
 perform public.registrar_impresion(m->>'folio');perform public.registrar_impresion(m->>'folio');
 perform set_config('test.multa',m->>'folio',true);
 perform public.turno_operador('cerrar');blocked:=false;
 begin perform public.ubicacion_operador(28.18,-105.47,10);exception when others then blocked:=SQLERRM like '%turno%';end;
 if not blocked then raise exception 'GPS sin turno permitido';end if;
end $$;
select set_config('request.jwt.claims',json_build_object('sub',current_setting('test.otro'),'role','authenticated')::text,true);
do $$begin if exists(select 1 from public.multas where folio=current_setting('test.multa')) then raise exception 'Otro operador ve multa ajena';end if;end $$;
reset role;
update public.perfiles set activo=false where user_id=current_setting('test.operador')::uuid;
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',current_setting('test.operador'),'role','authenticated')::text,true);
do $$declare blocked boolean:=false;begin begin perform public.turno_operador('iniciar');exception when others then blocked:=SQLERRM like '%Acceso denegado%';end;if not blocked then raise exception 'Usuario desactivado puede operar';end if;end $$;
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
do $$declare r jsonb;begin
 r:=public.seguir_reporte(current_setting('test.folio'),current_setting('test.token')::uuid);if r is null then raise exception 'Seguimiento correcto no funciona';end if;
 if public.seguir_reporte(current_setting('test.folio'),gen_random_uuid()) is not null then raise exception 'Token inválido revela reporte';end if;
 if exists(select 1 from public.reportes) then raise exception 'Anónimo lee reportes';end if;
 if has_function_privilege('anon','public.alertar_reporte(uuid,uuid)','execute') then raise exception 'Anónimo puede alertar';end if;
end $$;
reset role;
select 'OK: turno, GPS, gracia, idempotencia reporte/multa, autoría, impresiones, RLS, suspensión y token' as verificacion;
rollback;
